events.command:
API_KEY="[REDACTED_GALAXY_API_KEY]"
COPY_HISTORY_ID="bbd44e69cb8906b5a639b46725e87e0e"

curl -s "https://usegalaxy.org/api/tools/toolshed.g2.bx.psu.edu/repos/iuc/filter_tabular/filter_tabular/3.3.1/build" \
  -H "x-api-key: ${API_KEY}" \
  -H "Content-Type: application/json" \
  -d "{\"history_id\": \"${COPY_HISTORY_ID}\"}" | python3 -c "
import json, sys
data = json.load(sys.stdin)
# Find the repeat section for linefilters
for inp in data['inputs']:
    if inp['name'] == 'linefilters':
        print('=== linefilters repeat ===')
        for sub in inp['inputs']:
            print(f'  name: {sub[\"name\"]}, type: {sub[\"type\"]}')
            if sub['type'] == 'conditional':
                for case in sub.get('cases', []):
                    print(f'    case value: {case[\"value\"]}')
                    for ci in case['inputs']:
                        print(f'      {ci[\"name\"]} ({ci[\"type\"]})')
"

